import React, { useState, useEffect, useCallback } from "react";
import axios from "axios";
import styled from "styled-components";
import { useParams } from "react-router-dom";

const EmployeePage = () => {
  const { id } = useParams(); // Lorry ID
  const [employeeName, setEmployeeName] = useState("");
  const [employeePhone, setEmployeePhone] = useState("");
  const [employeeRole, setEmployeeRole] = useState("driver"); // Default role
  const [employeeSalary, setEmployeeSalary] = useState("");
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [isFormVisible, setFormVisible] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [salaryDetails, setSalaryDetails] = useState(null);

  // Fetch employees by role dynamically
  const fetchEmployeesByRole = useCallback(
    async (role) => {
      try {
        const response = await axios.get(
          `http://localhost:5001/api/employee/employeesByRole/${id}/${role}`
        );
        setFilteredEmployees(response.data); // Update state with employees data
      } catch (error) {
        console.error("Error fetching employees:", error);
      }
    },
    [id]
  );

  // Fetch salary details for the selected employee
  const fetchSalaryDetails = async (employeeId) => {
    const currentMonth = new Date().getMonth() + 1; // Current month (1-12)
    const currentYear = new Date().getFullYear(); // Current year (e.g., 2024)

    try {
      const response = await axios.get(
        `http://localhost:5001/api/employeeSalary/${employeeId}/${currentYear}/${currentMonth}`
      );
      setSalaryDetails(response.data);
    } catch (error) {
      console.error("Error fetching salary details:", error);
      alert("Salary details not found.");
    }
  };

  // Handle employee click to show details and salary
  const handleEmployeeClick = async (employee) => {
    console.log(employee); // Log the employee object to check if 'id' is present
    if (!employee.id) {
      alert("Employee ID is missing");
      return;
    }
    setSelectedEmployee(employee);
    fetchSalaryDetails(employee.id); // Fetch salary details for this employee
  };


  // Handle employee addition
  const addEmployee = async () => {
    try {
      const newEmployee = {
        name: employeeName,
        phone: employeePhone,
        role: employeeRole,
        fixed_salary: employeeSalary,
        lorry_id: id,
      };
      await axios.post("http://localhost:5001/api/employee/add", newEmployee);
      alert("Employee added successfully");
      fetchEmployeesByRole(employeeRole); // Refresh the employee list
      setFormVisible(false); // Hide form after adding employee
    } catch (error) {
      console.error("Error adding employee:", error);
      alert("Error adding employee");
    }
  };

  // Handle employee deletion
  const handleDeleteEmployee = async (employeePhone) => {
    try {
      await axios.delete(`http://localhost:5001/api/employee/${employeePhone}`);
      alert("Employee deleted successfully");
      fetchEmployeesByRole(employeeRole); // Refresh the employee list after deletion
      setSelectedEmployee(null); // Close the employee details modal
    } catch (error) {
      console.error("Error deleting employee:", error);
      alert("Error deleting employee");
    }
  };

  // Fetch employees when the role or lorry ID changes
  useEffect(() => {
    fetchEmployeesByRole(employeeRole);
  }, [employeeRole, id, fetchEmployeesByRole]); // Dependencies include employeeRole and lorry ID

  const handleRoleChange = (role) => {
    setEmployeeRole(role); // Update selected role
    fetchEmployeesByRole(role); // Fetch employees based on selected role
  };

  return (
    <Container>
      <Header>
        <LorryTitle>Lorry {id}</LorryTitle>
      </Header>

      <Button onClick={() => setFormVisible(!isFormVisible)}>
        {isFormVisible ? "Cancel" : "Add Employee"}
      </Button>

      {isFormVisible && (
        <Form>
          <Input
            type="text"
            placeholder="Employee Name"
            value={employeeName}
            onChange={(e) => setEmployeeName(e.target.value)}
          />
          <Input
            type="text"
            placeholder="Phone Number"
            value={employeePhone}
            onChange={(e) => setEmployeePhone(e.target.value)}
          />
          <Select
            value={employeeRole}
            onChange={(e) => setEmployeeRole(e.target.value)}
          >
            <option value="driver">Driver</option>
            <option value="driller">Driller</option>
            <option value="manager">Manager</option>
            <option value="worker">Worker</option>
          </Select>
          <Input
            type="number"
            placeholder="Fixed Salary"
            value={employeeSalary}
            onChange={(e) => setEmployeeSalary(e.target.value)}
          />
          <Button onClick={addEmployee}>Add Employee</Button>
        </Form>
      )}

      {/* Role Tabs */}
      <EmployeeRoles>
        <RoleTabs>
          <Tab onClick={() => handleRoleChange("driver")}>Drivers</Tab>
          <Tab onClick={() => handleRoleChange("driller")}>Drillers</Tab>
          <Tab onClick={() => handleRoleChange("manager")}>Managers</Tab>
          <Tab onClick={() => handleRoleChange("worker")}>Workers</Tab>
        </RoleTabs>

        {/* Employee List */}
        <EmployeeList>
  {filteredEmployees.length > 0 ? (
    filteredEmployees.map((employee) => (
      <EmployeeItem
        key={employee.phone, employee.id} // Using 'phone' here may not guarantee uniqueness
        onClick={() => handleEmployeeClick(employee)}
      >
        {employee.name} ({employee.phone})
      </EmployeeItem>
    ))
  ) : (
    <EmployeeItem>No employees found for this role.</EmployeeItem>
  )}
</EmployeeList>
      </EmployeeRoles>

      {/* Employee Details Modal */}
      {selectedEmployee && (
        <EmployeeDetails>
          <h3>
            {selectedEmployee.name} ({selectedEmployee.phone})
          </h3>

          {/* Employee Salary Details */}
          {salaryDetails && (
            <CardContainer>
              <Card>
                <CardTitle>Salary Per Day</CardTitle>
                <CardContent>{salaryDetails.salary_per_day}</CardContent>
              </Card>
              <Card>
                <CardTitle>Days Worked</CardTitle>
                <CardContent>{salaryDetails.days_worked}</CardContent>
              </Card>
              <Card>
                <CardTitle>Expense</CardTitle>
                <CardContent>{salaryDetails.expense}</CardContent>
              </Card>
              <Card>
                <CardTitle>Earned</CardTitle>
                <CardContent>{salaryDetails.earned}</CardContent>
              </Card>
            </CardContainer>
          )}

          <Button onClick={() => handleDeleteEmployee(selectedEmployee.phone)}>
            Delete Employee
          </Button>
        </EmployeeDetails>
      )}
    </Container>
  );
};

export default EmployeePage;

// Styled Components
const Container = styled.div`
  padding: 20px;
  background-color: #f4f7fc;
`;

const Header = styled.header`
  display: flex;
  justify-content: center;
  padding: 20px;
  background-color: #ffffff;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const LorryTitle = styled.h1`
  font-size: 2rem;
  font-weight: bold;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: #4caf50;
  color: white;
  font-size: 1.1rem;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  margin-top: 20px;

  &:hover {
    background-color: #45a049;
  }
`;

const Form = styled.div`
  background-color: #ffffff;
  padding: 20px;
  margin-top: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const Input = styled.input`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const Select = styled.select`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const EmployeeRoles = styled.div`
  margin-top: 30px;
`;

const RoleTabs = styled.div`
